// ============================================================================
// Differential corpus tests for core/tools/render-utils.ts and core/tools/renderers/*.ts (4f-1).
//
// The corpus is generated by tools/gen-toolrenderers-corpus.mjs, which *executes the upstream
// TypeScript renderers themselves* — only their `import` specifiers are redirected, to staged copies
// of the upstream helper modules and to local stubs. What it records is the **component tree** each
// renderer produces plus the exact string each component was given: rendered lines cannot observe the
// framing decisions (a `Box` with `paddingX: 2` and one with `paddingX: 0` produce the same text), and
// framing is precisely what this phase had to get right.
//
// The component classes on the JS side are recording stubs, because `Text`/`Box`/`Spacer`/`Container`
// were ported and differentially verified in earlier phases (tests/Pi.Tui.Tests) and re-testing their
// wrapping here would duplicate that. The C# side walks the *real* components through the read-only
// state accessors they expose (`Text.CurrentText`, `Box.PaddingX`, `Spacer.Lines`,
// `VisualLinePreview.Options`, …), so the comparison is between the real port and the upstream
// renderer logic, not between two stubs.
//
// Styling is compared byte-for-byte: the generator's theme stub emits the same escape sequences the
// real `Theme` class does, over the synthetic colour table in the corpus's `theme` block, and the test
// builds a real `Theme` from that table and installs it with `ThemeRuntime.SetThemeInstance`.
// ============================================================================

using System.Globalization;
using System.Text.Json;
using System.Text.Json.Nodes;
using Pi.Agent.Types;
using Pi.Ai.Types;
using Pi.CodingAgent;
using Pi.CodingAgent.Core.Extensions;
using Pi.CodingAgent.Core.Tools;
using Pi.CodingAgent.Core.Tools.Renderers;
using Pi.CodingAgent.Modes.Interactive;
using Pi.CodingAgent.Modes.Interactive.Components;
using Pi.CodingAgent.Utils;
using Pi.Tui;
using Xunit;
using Box = Pi.Tui.Components.Box;
using Text = Pi.Tui.Components.Text;

namespace Pi.CodingAgent.Tests;

public sealed class ToolRenderersCorpusTests : IDisposable
{
    private const string CorpusFileName = "tool-renderers-corpus.json";

    /// <summary>Hidden-line counts the generator probes each <c>formatHint</c> closure with.</summary>
    private static readonly int[] HintCounts = [0, 1, 3, 7, 42];

    private readonly bool? _previousChalk = Chalk.EnabledOverride;

    public ToolRenderersCorpusTests()
    {
        // The corpus records escape sequences, so colour has to be on regardless of the host terminal.
        Chalk.EnabledOverride = true;
        ThemeRuntime.ResetCachesForTests();
        TerminalImage.ResetCapabilitiesCache();
        ThemeRuntime.SetThemeInstance(Corpus.Theme);
    }

    public void Dispose()
    {
        BashRenderers.NowOverride = null;
        Chalk.EnabledOverride = _previousChalk;
        ThemeRuntime.ResetCachesForTests();
        TerminalImage.ResetCapabilitiesCache();
    }

    // ------------------------------------------------------------------ corpus loading

    private sealed record Step(
        string Kind,
        long NowMs,
        JsonObject? Args,
        string Cwd,
        bool Expanded,
        bool IsPartial,
        bool ShowImages,
        bool IsError,
        bool ArgsComplete,
        bool ExecutionStarted,
        long? DurationMs,
        int OutputPad,
        bool OptionsExpanded,
        bool OptionsPartial,
        JsonNode? Content,
        JsonNode? Details,
        JsonNode? CallTree,
        JsonNode? ResultTree);

    private sealed record Case(
        string Id,
        string Tool,
        string Capability,
        string Cwd,
        string Images,
        bool TrueColor,
        bool Hyperlinks,
        IReadOnlyList<Step> Steps);

    private sealed record IndexSurface(
        IReadOnlyList<string> ToolNames,
        IReadOnlyDictionary<string, (bool Call, bool Result)> Slots,
        IReadOnlyList<(string Name, IReadOnlyList<string> Keys)> Merge);

    private sealed record CorpusData(
        Theme Theme,
        string PackageRoot,
        IndexSurface IndexSurface,
        IReadOnlyList<Case> Cases);

    private static CorpusData Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, CorpusFileName);
        using var document = JsonDocument.Parse(File.ReadAllText(path));
        var root = document.RootElement;

        var theme = root.GetProperty("theme");
        var colors = new Dictionary<string, ThemeJsonColorValue>(StringComparer.Ordinal);
        foreach (var entry in theme.GetProperty("colors").EnumerateObject())
        {
            colors[entry.Name] = entry.Value.GetString()!;
        }

        var backgrounds = new Dictionary<string, ThemeJsonColorValue>(StringComparer.Ordinal);
        foreach (var entry in theme.GetProperty("backgrounds").EnumerateObject())
        {
            backgrounds[entry.Name] = entry.Value.GetString()!;
        }

        var dim = theme.GetProperty("dim").EnumerateArray().Select(item => item.GetString()!).ToList();
        var themeInstance = new Theme(
            colors,
            backgrounds,
            TerminalColorMode.Truecolor,
            new ThemeOptions { Name = "tool-renderers-corpus", Appearance = ThemeAppearance.Dark, Dim = dim });

        var surface = root.GetProperty("indexSurface");
        var slots = new Dictionary<string, (bool, bool)>(StringComparer.Ordinal);
        foreach (var entry in surface.GetProperty("slots").EnumerateObject())
        {
            slots[entry.Name] = (
                entry.Value.GetProperty("renderCall").GetBoolean(),
                entry.Value.GetProperty("renderResult").GetBoolean());
        }

        var merge = surface.GetProperty("merge")
            .EnumerateArray()
            .Select(item => (
                item[0].GetString()!,
                (IReadOnlyList<string>)item[1].EnumerateArray().Select(key => key.GetString()!).ToList()))
            .ToList();

        var cases = new List<Case>();
        foreach (var element in root.GetProperty("cases").EnumerateArray())
        {
            var capabilities = element.GetProperty("capabilities");
            cases.Add(new Case(
                element.GetProperty("id").GetString()!,
                element.GetProperty("tool").GetString()!,
                element.GetProperty("capability").GetString()!,
                element.GetProperty("cwd").GetString()!,
                capabilities.GetProperty("images").GetString()!,
                capabilities.GetProperty("trueColor").GetBoolean(),
                capabilities.GetProperty("hyperlinks").GetBoolean(),
                element.GetProperty("steps").EnumerateArray().Select(ReadStep).ToList()));
        }

        return new CorpusData(
            themeInstance,
            root.GetProperty("packageRoot").GetString()!,
            new IndexSurface(
                surface.GetProperty("toolNames").EnumerateArray().Select(item => item.GetString()!).ToList(),
                slots,
                merge),
            cases);
    }

    private static Step ReadStep(JsonElement element)
    {
        var context = element.GetProperty("context");
        var kind = element.GetProperty("kind").GetString()!;
        var options = kind == "result" ? element.GetProperty("options") : default;
        return new Step(
            kind,
            element.GetProperty("nowMs").GetInt64(),
            context.TryGetProperty("args", out var args) ? (JsonObject)JsonNode.Parse(args.GetRawText())! : null,
            context.GetProperty("cwd").GetString()!,
            context.GetProperty("expanded").GetBoolean(),
            context.GetProperty("isPartial").GetBoolean(),
            context.GetProperty("showImages").GetBoolean(),
            context.GetProperty("isError").GetBoolean(),
            context.GetProperty("argsComplete").GetBoolean(),
            context.GetProperty("executionStarted").GetBoolean(),
            context.GetProperty("durationMs").ValueKind == JsonValueKind.Null
                ? null
                : context.GetProperty("durationMs").GetInt64(),
            context.GetProperty("outputPad").GetInt32(),
            options.ValueKind != JsonValueKind.Undefined
                && options.TryGetProperty("expanded", out var expanded) && expanded.GetBoolean(),
            options.ValueKind != JsonValueKind.Undefined
                && options.TryGetProperty("isPartial", out var partial) && partial.GetBoolean(),
            element.TryGetProperty("content", out var content) ? JsonNode.Parse(content.GetRawText()) : null,
            element.TryGetProperty("details", out var details) ? JsonNode.Parse(details.GetRawText()) : null,
            ReadTree(element, "callTree"),
            ReadTree(element, "resultTree"));

        static JsonNode? ReadTree(JsonElement element, string name) =>
            element.TryGetProperty(name, out var tree) && tree.ValueKind != JsonValueKind.Null
                ? JsonNode.Parse(tree.GetRawText())
                : null;
    }

    private static readonly CorpusData Corpus = Load();

    /// <summary>
    /// The root the corpus recorded for `getReadmePath()`'s directory. `read.ts` classifies a path as a
    /// pi doc by testing whether it sits under that directory, so recorded paths are rewritten onto the
    /// root the port's own <see cref="Config.GetReadmePath"/> reports — the classification logic is what
    /// is under test here, not the deployment layout.
    /// </summary>
    private static readonly string PortPackageRoot = Path.GetDirectoryName(Config.GetReadmePath())!;

    public static TheoryData<int> CaseIndexes()
    {
        var data = new TheoryData<int>();
        for (var index = 0; index < Corpus.Cases.Count; index++)
        {
            data.Add(index);
        }

        return data;
    }

    [Fact]
    public void Corpus_HasTheExpectedShape()
    {
        Assert.Equal(104, Corpus.Cases.Count);
        Assert.Equal(270, Corpus.Cases.Sum(item => item.Steps.Count));
        Assert.All(Corpus.Cases, item => Assert.False(string.IsNullOrEmpty(item.Id)));

        // Every foreground and background token, so a renderer reaching for an unstyled token would
        // throw in the generator rather than pass silently here.
        Assert.Equal(ThemeTokens.All.Count, Corpus.Theme.Colors.Count);
        Assert.Equal(8, Corpus.IndexSurface.ToolNames.Count);
    }

    /// <summary>
    /// The corpus's `highlightCode` stub reproduces what the port's *default* tokenizer produces, which
    /// is what makes the replay meaningful without a highlight.js binding (divergence C23). If a real
    /// tokenizer is ever installed, this fails first and says why.
    /// </summary>
    [Fact]
    public void HighlightStub_MatchesTheDefaultTokenizer()
    {
        Assert.Null(SyntaxHighlight.HighlighterOverride);
        Assert.False(SyntaxHighlight.SupportsLanguage("typescript"));
        Assert.Equal(
            ["\u001b[38;2;24;0;0mconst a = 1;\u001b[39m"],
            ThemeHelpers.HighlightCode("const a = 1;", "typescript"));
    }

    // ------------------------------------------------------------------ the replay

    [Theory]
    [MemberData(nameof(CaseIndexes))]
    public void CorpusCase_ProducesTheUpstreamComponentTree(int index) => RunCase(Corpus.Cases[index]);

    private static void RunCase(Case testCase)
    {
        TerminalImage.SetCapabilities(new TerminalCapabilities(
            testCase.Images switch
            {
                "kitty" => ImageProtocol.Kitty,
                "iterm2" => ImageProtocol.Iterm2,
                _ => ImageProtocol.None,
            },
            testCase.TrueColor,
            testCase.Hyperlinks));

        var renderers = RenderersFor(testCase.Tool);
        var state = StateFor(testCase.Tool);
        var callArgs = testCase.Steps.FirstOrDefault(step => step.Kind == "call")?.Args;

        IComponent? callSlot = null;
        IComponent? resultSlot = null;

        try
        {
            foreach (var step in testCase.Steps)
            {
                BashRenderers.NowOverride = () => step.NowMs;
                var args = step.Kind == "call" ? step.Args : callArgs;
                var context = new ToolRenderContext
                {
                    Args = ArgsToClr(args),
                    ToolCallId = "call-1",
                    Invalidate = () => { },
                    LastComponent = step.Kind == "call" ? callSlot : resultSlot,
                    State = state,
                    Cwd = step.Cwd,
                    ExecutionStarted = step.ExecutionStarted,
                    ArgsComplete = step.ArgsComplete,
                    IsPartial = step.IsPartial,
                    Expanded = step.Expanded,
                    ShowImages = step.ShowImages,
                    IsError = step.IsError,
                    DurationMs = step.DurationMs,
                    OutputPad = step.OutputPad,
                };

                if (step.Kind == "call")
                {
                    callSlot = renderers.RenderCall!(ArgsToClr(args), Corpus.Theme, context);
                }
                else
                {
                    var result = new AgentToolResult(
                        ToContent(step.Content),
                        DetailsFor(testCase.Tool, step.Details),
                        IsError: step.IsError);
                    resultSlot = renderers.RenderResult!(
                        result,
                        new ToolRenderResultOptions(step.OptionsExpanded, step.OptionsPartial),
                        Corpus.Theme,
                        context);
                }

                AssertTree(step.CallTree, callSlot, $"{testCase.Id}: {step.Kind} → call slot");
                AssertTree(step.ResultTree, resultSlot, $"{testCase.Id}: {step.Kind} → result slot");
            }
        }
        finally
        {
            // A partial shell result arms a one-second tick; leaving it running would keep firing into
            // a disposed test.
            if (state is ShellRenderState shell)
            {
                shell.Interval?.Dispose();
                shell.Interval = null;
            }
        }
    }

    private static void AssertTree(JsonNode? expected, IComponent? actual, string label)
    {
        var actualJson = Render(Normalize(actual));
        var expectedJson = Render(expected);
        if (!string.Equals(expectedJson, actualJson, StringComparison.Ordinal))
        {
            Assert.Fail($"{label}\nexpected:\n{expectedJson}\nactual:\n{actualJson}");
        }

        static string Render(JsonNode? node) => node is null
            ? "null"
            : node.ToJsonString(new JsonSerializerOptions { WriteIndented = true });
    }

    private static ToolRenderers RenderersFor(string tool) => tool switch
    {
        "ls" => LsRenderers.Value,
        "find" => FindRenderers.Value,
        "grep" => GrepRenderers.Value,
        "read" => ReadRenderers.Value,
        "write" => WriteRenderers.Value,
        "edit" => EditRenderers.Value,
        "bash" => BashRenderers.CreateShellRenderers("$"),
        "powershell" => BashRenderers.CreateShellRenderers("PS>"),
        _ => throw new InvalidOperationException($"no renderer for {tool}"),
    };

    private static object? StateFor(string tool) => tool switch
    {
        "bash" or "powershell" => new ShellRenderState(),
        "edit" => new EditRenderState(),
        _ => null,
    };

    // ------------------------------------------------------------------ the component tree, normalised

    private static JsonNode? Normalize(IComponent? node)
    {
        switch (node)
        {
            case null:
                return null;

            case VisualLinePreview preview:
            {
                var options = preview.Options;
                var hints = new JsonObject();
                foreach (var count in HintCounts)
                {
                    hints[count.ToString(CultureInfo.InvariantCulture)] = options.FormatHint(count);
                }

                return new JsonObject
                {
                    ["type"] = "VisualLinePreview",
                    ["text"] = options.Text,
                    ["maxVisualLines"] = options.MaxVisualLines,
                    ["keep"] = options.Keep,
                    ["hints"] = hints,
                };
            }

            case Pi.Tui.Components.Spacer spacer:
                return new JsonObject { ["type"] = "Spacer", ["lines"] = spacer.Lines };

            case EditCallRenderComponent edit:
                return NormalizeBox(edit, withPreview: true);

            case Box box:
                return NormalizeBox(box, withPreview: false);

            case Container container:
            {
                var children = new JsonArray();
                foreach (var child in container.Children)
                {
                    children.Add(Normalize(child));
                }

                return new JsonObject { ["type"] = "Container", ["children"] = children };
            }

            case Text text:
                return NormalizeText(text);

            default:
                throw new InvalidOperationException($"unknown component in the renderer tree: {node.GetType().Name}");
        }
    }

    private static JsonNode NormalizeBox(Box box, bool withPreview)
    {
        var children = new JsonArray();
        foreach (var child in box.Children)
        {
            children.Add(Normalize(child));
        }

        var tree = new JsonObject
        {
            ["type"] = "Box",
            ["paddingX"] = box.PaddingX,
            ["paddingY"] = box.PaddingY,
            ["background"] = Probe(box.BgFn),
            ["children"] = children,
        };

        if (!withPreview)
        {
            return tree;
        }

        var edit = (EditCallRenderComponent)box;
        tree["preview"] = edit.Preview switch
        {
            null => null,
            { Error: not null } preview => new JsonObject { ["kind"] = "error", ["error"] = preview.Error },
            { } preview => new JsonObject
            {
                ["kind"] = "diff",
                ["diff"] = preview.Diff,
                ["firstChangedLine"] = preview.FirstChangedLine is { } line ? JsonValue.Create(line) : null,
            },
        };
        tree["previewArgsKey"] = edit.PreviewArgsKey;
        tree["previewPending"] = edit.PreviewPending;
        tree["settledError"] = edit.SettledError;
        return tree;
    }

    private static JsonNode NormalizeText(Text text)
    {
        var tree = new JsonObject
        {
            ["type"] = "Text",
            ["text"] = text.CurrentText,
            ["paddingX"] = text.PaddingX,
            ["paddingY"] = text.PaddingY,
            ["background"] = Probe(text.CustomBgFn),
        };

        if (text is WriteCallRenderComponent write)
        {
            // The cache object is mutated in place as the content argument streams in, so the arrays are
            // copied here exactly as the generator copies them: an earlier step's record must show the
            // lines it had at the time, not the lines it ended up with.
            tree["cache"] = write.Cache is { } cache
                ? new JsonObject
                {
                    ["rawPath"] = cache.RawPath,
                    ["lang"] = cache.Lang,
                    ["rawContent"] = cache.RawContent,
                    ["normalizedLines"] = new JsonArray(
                        [.. cache.NormalizedLines.Select(line => (JsonNode?)JsonValue.Create(line))]),
                    ["highlightedLines"] = new JsonArray(
                        [.. cache.HighlightedLines.Select(line => (JsonNode?)JsonValue.Create(line))]),
                }
                : null;
        }

        return tree;
    }

    /// <summary>
    /// Run a background closure with a marker, so the corpus observes *which* token it paints with
    /// rather than merely that one exists.
    /// </summary>
    private static JsonNode? Probe(Func<string, string>? background) =>
        background is null ? null : background("<bg>");

    // ------------------------------------------------------------------ corpus JSON to runtime values

    /// <summary>
    /// The runtime hands tools a JSON-shaped object graph with plain CLR leaves — that is the shape
    /// <see cref="ToolRenderContext.Args"/> carries and the one <see cref="RenderUtils.Arg"/>'s
    /// dictionary branch reads — so the corpus's arguments are rebuilt that way rather than left as
    /// <see cref="JsonNode"/>s, which would silently take every <c>str()</c> down its "wrong type" path.
    /// </summary>
    private static IReadOnlyDictionary<string, object?> ArgsToClr(JsonObject? args) =>
        args is null
            ? new Dictionary<string, object?>()
            : args.ToDictionary(
                pair => pair.Key,
                pair => ToClr(pair.Value, rewriteRoot: true),
                StringComparer.Ordinal);

    private static object? ToClr(JsonNode? node, bool rewriteRoot) => node switch
    {
        null => null,
        JsonObject json => json.ToDictionary(
            pair => pair.Key,
            pair => ToClr(pair.Value, rewriteRoot),
            StringComparer.Ordinal),
        JsonArray array => array.Select(item => ToClr(item, rewriteRoot)).ToList(),
        JsonValue value when value.GetValueKind() == JsonValueKind.String =>
            rewriteRoot ? RewriteRoot(value.GetValue<string>()) : value.GetValue<string>(),
        JsonValue value => ClrScalar(value),
        _ => null,
    };

    private static object? ClrScalar(JsonValue value) => value.GetValueKind() switch
    {
        JsonValueKind.Number => value.GetValue<double>(),
        JsonValueKind.True => true,
        JsonValueKind.False => false,
        _ => null,
    };

    private static string RewriteRoot(string value) =>
        value.Replace(Corpus.PackageRoot, PortPackageRoot, StringComparison.OrdinalIgnoreCase);

    private static List<ContentBlock> ToContent(JsonNode? content)
    {
        var blocks = new List<ContentBlock>();
        if (content is not JsonArray array)
        {
            return blocks;
        }

        foreach (var item in array)
        {
            switch (item?["type"]?.GetValue<string>())
            {
                case "text":
                    blocks.Add(new TextContent(item["text"]?.GetValue<string>() ?? ""));
                    break;
                case "image":
                    blocks.Add(new ImageContent(
                        item["data"]?.GetValue<string>() ?? "",
                        item["mimeType"]?.GetValue<string>()));
                    break;
            }
        }

        return blocks;
    }

    /// <summary>
    /// Rebuild the tool-specific <c>details</c> payload. The renderers narrow it by CLR type, so a
    /// generic dictionary would silently take every <c>details?.x</c> read down the null path.
    /// </summary>
    private static object? DetailsFor(string tool, JsonNode? details)
    {
        if (details is not JsonObject json || json.Count == 0)
        {
            return null;
        }

        var truncation = json["truncation"] is JsonObject raw ? ReadTruncation(raw) : null;
        return tool switch
        {
            "ls" => new LsToolDetails
            {
                Truncation = truncation,
                EntryLimitReached = Int(json["entryLimitReached"]),
            },
            "find" => new FindToolDetails
            {
                Truncation = truncation,
                ResultLimitReached = Int(json["resultLimitReached"]),
            },
            "grep" => new GrepToolDetails
            {
                Truncation = truncation,
                MatchLimitReached = Int(json["matchLimitReached"]),
                LinesTruncated = json["linesTruncated"]?.GetValue<bool>(),
            },
            "read" => new ReadToolDetails { Truncation = truncation },
            "edit" => new EditToolDetails
            {
                Diff = json["diff"]?.GetValue<string>() ?? "",
                Patch = json["patch"]?.GetValue<string>() ?? "",
                FirstChangedLine = Int(json["firstChangedLine"]),
            },
            "bash" or "powershell" => new BashToolDetails
            {
                Truncation = truncation,
                FullOutputPath = json["fullOutputPath"]?.GetValue<string>(),
            },
            _ => null,
        };

        static int? Int(JsonNode? node) => node is null ? null : (int)node.GetValue<double>();
    }

    private static Truncate.TruncationResult ReadTruncation(JsonObject json) => new()
    {
        Content = json["content"]?.GetValue<string>() ?? "",
        Truncated = json["truncated"]?.GetValue<bool>() ?? false,
        TruncatedBy = json["truncatedBy"]?.GetValue<string>(),
        TotalLines = (int)(json["totalLines"]?.GetValue<double>() ?? 0),
        TotalBytes = (int)(json["totalBytes"]?.GetValue<double>() ?? 0),
        OutputLines = (int)(json["outputLines"]?.GetValue<double>() ?? 0),
        OutputBytes = (int)(json["outputBytes"]?.GetValue<double>() ?? 0),
        LastLinePartial = json["lastLinePartial"]?.GetValue<bool>() ?? false,
        FirstLineExceedsLimit = json["firstLineExceedsLimit"]?.GetValue<bool>() ?? false,
        MaxLines = (int)(json["maxLines"]?.GetValue<double>() ?? 0),
        MaxBytes = (int)(json["maxBytes"]?.GetValue<double>() ?? 0),
    };

    // ------------------------------------------------------------------ renderers/index.ts

    [Fact]
    public void CreateAllToolRenderers_RegistersEveryBuiltInTool()
    {
        var actual = BuiltInToolRenderers.CreateAllToolRenderers();
        Assert.Equal(
            Corpus.IndexSurface.ToolNames,
            actual.Keys.OrderBy(name => name, StringComparer.Ordinal).ToList());

        foreach (var (name, expected) in Corpus.IndexSurface.Slots)
        {
            Assert.True(actual.ContainsKey(name), $"{name} is missing from the built-in renderer map");
            Assert.Equal(expected.Call, actual[name].RenderCall is not null);
            Assert.Equal(expected.Result, actual[name].RenderResult is not null);
        }
    }

    [Fact]
    public void WithBuiltInRenderers_FillsOnlyTheEmptySlots()
    {
        foreach (var (name, expected) in Corpus.IndexSurface.Merge)
        {
            // The generator drives `withBuiltInRenderers` with "ls" for every case except the unknown
            // tool name, which is the one that must come back without renderers at all.
            var toolName = name.StartsWith("unknown", StringComparison.Ordinal) ? "nope" : "ls";
            var definition = name switch
            {
                "known/partial" => new ToolRenderers { RenderCall = (_, _, _) => new Text("", 0, 0) },
                "undefined/empty" => null,
                _ => new ToolRenderers(),
            };

            var merged = BuiltInToolRenderers.WithBuiltInRenderers(toolName, definition);
            Assert.NotNull(merged);

            var actual = new List<string>();
            if (merged!.RenderCall is not null)
            {
                actual.Add("renderCall");
            }

            if (merged.RenderResult is not null)
            {
                actual.Add("renderResult");
            }

            if (merged.RenderShell is not null)
            {
                actual.Add("renderShell");
            }

            Assert.Equal(expected, actual.OrderBy(key => key, StringComparer.Ordinal).ToList());
        }
    }

    // ------------------------------------------------------------------ read.ts's docs classification

    /// <summary>
    /// `read.ts` recognises a pi doc by testing whether the path sits under the readme's directory.
    /// The corpus pins that directory to the pi checkout and the replay rewrites it onto this build's
    /// own, so this drives the rewritten form end to end and fails loudly if the port's root stops
    /// working as a docs root.
    /// </summary>
    [Fact]
    public void ReadCall_ClassifiesAPathUnderThePortsOwnPackageRootAsDocs()
    {
        var args = new Dictionary<string, object?>(StringComparer.Ordinal)
        {
            ["path"] = Path.Combine(PortPackageRoot, "docs", "guide.md"),
        };
        var context = new ToolRenderContext
        {
            Args = args,
            ToolCallId = "call-1",
            Invalidate = () => { },
            Cwd = "D:/work/proj",
        };

        var component = (Text)ReadRenderers.Value.RenderCall!(args, Corpus.Theme, context);
        Assert.Contains("read docs", component.CurrentText, StringComparison.Ordinal);
        Assert.Contains("docs/guide.md", component.CurrentText, StringComparison.Ordinal);
    }

    // ------------------------------------------------------------------ the asynchronous preview

    /// <summary>
    /// The corpus deliberately never starts edit's background preview (every edit case renders with
    /// <c>argsComplete: false</c>), because the renderer only observes the promise through a later
    /// invalidation. This covers that path directly: a real file on disk, a completed preview, and the
    /// call component rebuilt around it.
    /// </summary>
    [Fact]
    public async Task EditPreview_IsComputedInTheBackgroundAndRebuildsTheCallComponent()
    {
        var directory = Path.Combine(Path.GetTempPath(), $"pi-edit-preview-{Guid.NewGuid():N}");
        Directory.CreateDirectory(directory);
        var file = Path.Combine(directory, "sample.txt");
        await File.WriteAllTextAsync(file, "one\ntwo\nthree\n");

        try
        {
            var args = new Dictionary<string, object?>(StringComparer.Ordinal)
            {
                ["path"] = file,
                ["edits"] = new List<object?>
                {
                    new Dictionary<string, object?>(StringComparer.Ordinal)
                    {
                        ["oldText"] = "two",
                        ["newText"] = "TWO",
                    },
                },
            };
            var context = new ToolRenderContext
            {
                Args = args,
                ToolCallId = "call-1",
                Invalidate = () => { },
                State = new EditRenderState(),
                Cwd = directory,
                ExecutionStarted = true,
                ArgsComplete = true,
                OutputPad = 1,
            };

            var component = (EditCallRenderComponent)EditRenderers.Value.RenderCall!(args, Corpus.Theme, context);
            Assert.True(component.PreviewPending);
            Assert.Null(component.Preview);

            var deadline = DateTime.UtcNow.AddSeconds(10);
            while (component.PreviewPending && DateTime.UtcNow < deadline)
            {
                await Task.Delay(20);
            }

            Assert.False(component.PreviewPending);
            Assert.NotNull(component.Preview);
            Assert.Null(component.Preview!.Error);
            Assert.Contains("TWO", component.Preview.Diff, StringComparison.Ordinal);

            // The preview arrives after the render, so the renderer's own invalidation is what makes the
            // rebuilt tree visible; `ToolExecutionComponent` (4f-3e) calls back into `renderCall`.
            var rebuilt = (EditCallRenderComponent)EditRenderers.Value.RenderCall!(args, Corpus.Theme, context);
            Assert.Same(component, rebuilt);
            Assert.Equal(3, rebuilt.Children.Count);
            Assert.Equal(1, ((Pi.Tui.Components.Spacer)rebuilt.Children[1]).Lines);
            Assert.Contains("TWO", ((Text)rebuilt.Children[2]).CurrentText, StringComparison.Ordinal);
        }
        finally
        {
            Directory.Delete(directory, recursive: true);
        }
    }
}
